const output = $input.first().json.stdout;
const metrics = JSON.parse(output.trim());
const timestamp = new Date().toISOString();

let alertLevel = 'NORMAL';
let alerts = [];

if (metrics.cpu_pct >= 95 || metrics.mem_pct >= 95 || metrics.disk_pct >= 95) {
  alertLevel = 'CRITICAL';
}
if (metrics.cpu_pct >= 80) alerts.push(`CPU: ${metrics.cpu_pct}%`);
if (metrics.mem_pct >= 80) alerts.push(`Memory: ${metrics.mem_pct}%`);
if (metrics.disk_pct >= 80) alerts.push(`Disk: ${metrics.disk_pct}%`);

if (alerts.length > 0 && alertLevel !== 'CRITICAL') {
  alertLevel = 'WARNING';
}

return [{
  json: {
    ...metrics,
    alertLevel,
    alerts: alerts.join(', ') || 'All normal',
    needsWarning: alertLevel === 'WARNING',
    needsCritical: alertLevel === 'CRITICAL',
    timestamp
  }
}];

